/**
 * The catalogue of convex polytopes of dimension 4 to 10 (docs/spaces/NDIM.md §2), as floats.
 *
 * Every polytope has unit edge and is centred at its vertex centroid, which is the origin. The data modules in ./data are
 * generated by python/ndim/gen_catalogue.py from exact vertices and facets that the generator proves (counts equal to the
 * literature, all edges exactly 1, a complete exact facet list). Codes are "<d>:<name>": simplex, cube (hypercube), ortho
 * (orthoplex, the cross-polytope), demi (demicube, d >= 5), 24cell, 120cell, 600cell (d = 4), 221 and 122 (d = 6, the
 * Gosset polytopes 2_21 and 1_22), 321 (d = 7), 421 (d = 8).
 *
 * The data of 8:421 (240 vertices, 19,440 facets, 2 MB of source) is loaded on demand: await loadPolytope("8:421") once;
 * getPolytope then returns it. The facts about every entry (counts, radii, volume) are in `INFO` and always available.
 */
import { INFO } from "./data/info";
import { D4 } from "./data/d4";
import { D5 } from "./data/d5";
import { D6 } from "./data/d6";
import { D7 } from "./data/d7";
import { D8 } from "./data/d8";
import { D9 } from "./data/d9";
import { D10 } from "./data/d10";

/** Facts about a polytope that do not need its coordinates. */
export interface PolytopeInfo {
  code: string;
  d: number;
  name: string;
  title: string;
  /** Vertices, edges and facets (the literature's counts, proved by the generator). */
  nV: number;
  nE: number;
  nF: number;
  /** Radius of the largest ball centred at the origin inside it: the smallest facet offset. */
  inradius: number;
  /** Largest distance of a vertex from the origin. */
  circumradius: number;
  /** d-dimensional volume of the unit-edge polytope (closed form where known, else Qhull's, about 1e-14 relative). */
  volume: number;
}

/** The generated floats of one polytope: vertices (nV x d), unit outward facet normals (nF x d) and offsets (nF). */
export interface PolytopeData {
  code: string;
  V: number[];
  N: number[];
  b: number[];
}

export interface Polytope extends PolytopeInfo {
  /** Vertices, row-major nV x d. */
  V: Float64Array;
  /** Unit outward facet normals, row-major nF x d: x in the polytope iff N_f . x <= b_f for all f. */
  N: Float64Array;
  /** Facet offsets b_f > 0. */
  b: Float64Array;
}

export const POLYTOPE_INFO: ReadonlyMap<string, PolytopeInfo> = new Map(INFO.map((i) => [i.code, i]));

/** All catalogue codes, by dimension and then name. */
export const POLYTOPE_CODES: readonly string[] = INFO.map((i) => i.code);

const cache = new Map<string, Polytope>();

function build(data: PolytopeData): Polytope {
  const info = POLYTOPE_INFO.get(data.code);
  if (!info) throw new Error(`no catalogue entry ${data.code}`);
  const p: Polytope = {
    ...info,
    V: Float64Array.from(data.V),
    N: Float64Array.from(data.N),
    b: Float64Array.from(data.b),
  };
  if (p.V.length !== p.nV * p.d || p.N.length !== p.nF * p.d || p.b.length !== p.nF)
    throw new Error(`${data.code}: data does not match its counts`);
  cache.set(data.code, p);
  return p;
}

const EAGER: PolytopeData[] = [...D4, ...D5, ...D6, ...D7, ...D8, ...D9, ...D10];
const eagerByCode = new Map(EAGER.map((e) => [e.code, e]));

/** Entries whose data is loaded with loadPolytope. */
export const LAZY_CODES: readonly string[] = ["8:421"];

/** The facts about a code; throws for an unknown code. */
export function polytopeInfo(code: string): PolytopeInfo {
  const i = POLYTOPE_INFO.get(code);
  if (!i) throw new Error(`unknown polytope code ${JSON.stringify(code)}`);
  return i;
}

/** Whether getPolytope(code) works now (the code exists and, for the lazy ones, has been loaded). */
export function isLoaded(code: string): boolean {
  return cache.has(code) || eagerByCode.has(code);
}

/** The polytope with its coordinates and facets. Throws for an unknown code, and for a lazy one that is not loaded yet. */
export function getPolytope(code: string): Polytope {
  const hit = cache.get(code);
  if (hit) return hit;
  const e = eagerByCode.get(code);
  if (e) return build(e);
  polytopeInfo(code);
  throw new Error(`${code} is loaded on demand: await loadPolytope(${JSON.stringify(code)}) first`);
}

/** Loads a polytope (the lazy ones from their module) and returns it. */
export async function loadPolytope(code: string): Promise<Polytope> {
  if (isLoaded(code)) return getPolytope(code);
  polytopeInfo(code);
  if (code === "8:421") return build((await import("./data/d8-421")).default);
  throw new Error(`no data module for ${code}`);
}

/** Codes of the catalogue in dimension d. */
export function polytopesOfDimension(d: number): string[] {
  return INFO.filter((i) => i.d === d).map((i) => i.code);
}
